const config = {
  "previewFeatures": [],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "mysql",
  "inlineSchema": "// ─────────────────────────────────────────────────────────────────────────────\n// schema.prisma — ClickServiço\n// Provider: MySQL  |  ORM: Prisma\n// ─────────────────────────────────────────────────────────────────────────────\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n}\n\n// ─── USERS (conta de login) ───────────────────────────────────────────────────\n// Um mesmo usuário pode ter perfil de cliente E/OU profissional.\nmodel User {\n  id        String   @id @default(uuid()) @db.VarChar(36)\n  name      String   @db.VarChar(150)\n  email     String   @unique @db.VarChar(191)\n  password  String   @db.VarChar(255) // hash bcrypt\n  phone     String?  @db.VarChar(20)\n  avatarUrl String?  @map(\"avatar_url\") @db.Text\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  // Um user pode ter ambos os perfis simultaneamente\n  client       Client?\n  professional Professional?\n\n  // Avaliações escritas pelo usuário (enquanto cliente)\n  testimonials Testimonial[]\n\n  chatMessages ChatMessage[]\n\n  @@map(\"users\")\n}\n\n// ─── CLIENTS (perfil cliente) ─────────────────────────────────────────────────\n// Criado quando o usuário se cadastra como cliente.\n// Simples — sem dados extras além do vínculo com users.\nmodel Client {\n  id        String   @id @default(uuid()) @db.VarChar(36)\n  userId    String   @unique @map(\"user_id\") @db.VarChar(36)\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  user   User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  orders Order[]\n\n  @@map(\"clients\")\n}\n\n// ─── PROFESSIONALS (perfil profissional) ─────────────────────────────────────\n// Requer dados adicionais de confirmação (CPF, endereço).\n// isVerified começa false e pode ser aprovado futuramente.\nmodel Professional {\n  id        String  @id @default(uuid()) @db.VarChar(36)\n  userId    String  @unique @map(\"user_id\") @db.VarChar(36)\n  specialty String? @db.VarChar(150) // ex: 'Eletricista Residencial'\n  bio       String? @db.Text\n  phone     String? @db.VarChar(20) // telefone de contato profissional\n\n  // Localização (exibida na busca)\n  location String? @db.VarChar(255) // ex: \"Santa Bárbara d'Oeste - SP\"\n\n  // Endereço completo\n  addressStreet       String? @map(\"address_street\") @db.VarChar(255)\n  addressNumber       String? @map(\"address_number\") @db.VarChar(20)\n  addressComplement   String? @map(\"address_complement\") @db.VarChar(100)\n  addressNeighborhood String? @map(\"address_neighborhood\") @db.VarChar(100)\n  addressCity         String? @map(\"address_city\") @db.VarChar(100)\n  addressState        String? @map(\"address_state\") @db.VarChar(2) // UF: 'SP'\n  addressCep          String? @map(\"address_cep\") @db.VarChar(10) // '13450-000'\n\n  // Dado de verificação\n  cpf         String? @unique @db.VarChar(14) // '000.000.000-00'\n  isVerified  Boolean @default(false) @map(\"is_verified\") // aprovado pelo admin\n  isAvailable Boolean @default(true) @map(\"is_available\") // visível na busca\n\n  // Métricas desnormalizadas para performance nas listagens\n  rating      Decimal @default(0.00) @db.Decimal(3, 2)\n  reviewCount Int     @default(0) @map(\"review_count\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  user           User                   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  categories     ProfessionalCategory[]\n  services       Service[]\n  orders         Order[]\n  portfolio      PortfolioItem[]\n  testimonials   Testimonial[]\n  appointments   Appointment[]\n  certifications Certification[]\n\n  @@map(\"professionals\")\n}\n\n// ─── CATEGORIES ───────────────────────────────────────────────────────────────\n// Imagens serão usadas futuramente via campo imageUrl ou CMS externo.\nmodel Category {\n  id          String   @id @default(uuid()) @db.VarChar(36)\n  name        String   @db.VarChar(100) // 'ENCANADOR'\n  slug        String   @unique @db.VarChar(100) // 'encanador'\n  description String?  @db.Text\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n\n  professionals ProfessionalCategory[]\n  services      Service[]\n  orders        Order[]\n  portfolio     PortfolioItem[]\n\n  @@map(\"categories\")\n}\n\n// ─── PROFESSIONAL_CATEGORIES (N:N) ───────────────────────────────────────────\n// Um profissional pode ter múltiplas especialidades/categorias.\nmodel ProfessionalCategory {\n  professionalId String @map(\"professional_id\") @db.VarChar(36)\n  categoryId     String @map(\"category_id\") @db.VarChar(36)\n\n  professional Professional @relation(fields: [professionalId], references: [id], onDelete: Cascade)\n  category     Category     @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n\n  @@id([professionalId, categoryId])\n  @@map(\"professional_categories\")\n}\n\n// ─── SERVICES ────────────────────────────────────────────────────────────────\n// Catálogo de serviços que um profissional oferece.\nmodel Service {\n  id             String        @id @default(uuid()) @db.VarChar(36)\n  professionalId String        @map(\"professional_id\") @db.VarChar(36)\n  categoryId     String?       @map(\"category_id\") @db.VarChar(36)\n  title          String        @db.VarChar(150) // 'Pintura Residencial'\n  priceText      String?       @map(\"price_text\") @db.VarChar(100) // 'A partir de R$ 25/m²'\n  priceValue     Decimal?      @map(\"price_value\") @db.Decimal(10, 2) // valor numérico\n  duration       String?       @db.VarChar(50) // '2 horas'\n  status         ServiceStatus @default(ativo)\n  createdAt      DateTime      @default(now()) @map(\"created_at\")\n  updatedAt      DateTime      @updatedAt @map(\"updated_at\")\n\n  professional Professional @relation(fields: [professionalId], references: [id], onDelete: Cascade)\n  category     Category?    @relation(fields: [categoryId], references: [id])\n  orders       Order[]\n\n  @@map(\"services\")\n}\n\nenum ServiceStatus {\n  ativo\n  inativo\n}\n\n// ─── ORDERS (pedidos) ─────────────────────────────────────────────────────────\n// O cliente envia um pedido → chega para o profissional como PENDENTE.\n// O profissional entra em contato, combina valores/datas\n// e atualiza para EM_ANDAMENTO, CONCLUIDO ou CANCELADO.\n//\n// Fluxo:\n//   Cliente preenche formulário → PENDENTE\n//   Profissional aceita e combina detalhes → EM_ANDAMENTO\n//   Serviço concluído → CONCLUIDO\n//   Qualquer lado cancela → CANCELADO\nmodel Order {\n  id             String      @id @default(uuid()) @db.VarChar(36)\n  clientId       String      @map(\"client_id\") @db.VarChar(36)\n  professionalId String      @map(\"professional_id\") @db.VarChar(36)\n  serviceId      String?     @map(\"service_id\") @db.VarChar(36) // serviço do catálogo (opcional)\n  categoryId     String?     @map(\"category_id\") @db.VarChar(36) // categoria do serviço\n  status         OrderStatus @default(PENDENTE)\n\n  // Dados preenchidos pelo cliente na solicitação\n  serviceType String? @map(\"service_type\") @db.VarChar(150) // 'Pintura Residencial'\n  description String? @db.Text // detalhes do que precisa\n  locationCep String? @map(\"location_cep\") @db.VarChar(10)\n  address     String? @db.Text\n  urgency     String? @db.VarChar(50) // 'o_mais_rapido', etc.\n  attachments Json? // URLs dos arquivos enviados\n\n  // Dados acordados com o profissional (preenchidos após contato)\n  agreedPrice Decimal?  @map(\"agreed_price\") @db.Decimal(10, 2) // valor combinado\n  scheduledAt DateTime? @map(\"scheduled_at\") // data/hora agendada\n  notes       String?   @db.Text\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  client       Client        @relation(fields: [clientId], references: [id])\n  professional Professional  @relation(fields: [professionalId], references: [id])\n  service      Service?      @relation(fields: [serviceId], references: [id])\n  category     Category?     @relation(fields: [categoryId], references: [id])\n  appointments Appointment[]\n  chatRoom     ChatRoom?\n\n  @@map(\"orders\")\n}\n\nenum OrderStatus {\n  PENDENTE\n  EM_ANDAMENTO\n  CONCLUIDO\n  CANCELADO\n}\n\n// ─── PORTFOLIO_ITEMS ──────────────────────────────────────────────────────────\nmodel PortfolioItem {\n  id             String   @id @default(uuid()) @db.VarChar(36)\n  professionalId String   @map(\"professional_id\") @db.VarChar(36)\n  categoryId     String?  @map(\"category_id\") @db.VarChar(36)\n  title          String   @db.VarChar(150)\n  imageUrl       String?  @map(\"image_url\") @db.Text\n  year           Int?\n  createdAt      DateTime @default(now()) @map(\"created_at\")\n\n  professional Professional @relation(fields: [professionalId], references: [id], onDelete: Cascade)\n  category     Category?    @relation(fields: [categoryId], references: [id])\n\n  @@map(\"portfolio_items\")\n}\n\n// ─── TESTIMONIALS ─────────────────────────────────────────────────────────────\nmodel Testimonial {\n  id             String   @id @default(uuid()) @db.VarChar(36)\n  professionalId String   @map(\"professional_id\") @db.VarChar(36)\n  authorId       String?  @map(\"author_id\") @db.VarChar(36) // null se depoimento externo/importado\n  authorName     String?  @map(\"author_name\") @db.VarChar(150) // fallback\n  authorRole     String?  @map(\"author_role\") @db.VarChar(100) // ex: 'Cliente'\n  content        String   @db.Text\n  rating         Int // 1 a 5\n  createdAt      DateTime @default(now()) @map(\"created_at\")\n\n  professional Professional @relation(fields: [professionalId], references: [id], onDelete: Cascade)\n  author       User?        @relation(fields: [authorId], references: [id])\n\n  @@map(\"testimonials\")\n}\n\n// ─── APPOINTMENTS ─────────────────────────────────────────────────────────────\n// Agendamentos/visitas técnicas gerados a partir de um pedido confirmado.\nmodel Appointment {\n  id             String            @id @default(uuid()) @db.VarChar(36)\n  orderId        String?           @map(\"order_id\") @db.VarChar(36) // nullable: pode existir sem order\n  professionalId String            @map(\"professional_id\") @db.VarChar(36)\n  clientId       String            @map(\"client_id\") @db.VarChar(36) // referência direta para queries rápidas\n  scheduledAt    DateTime          @map(\"scheduled_at\")\n  address        String?           @db.Text\n  serviceName    String?           @map(\"service_name\") @db.VarChar(150)\n  status         AppointmentStatus @default(CONFIRMADO)\n  notes          String?           @db.Text\n  createdAt      DateTime          @default(now()) @map(\"created_at\")\n\n  order        Order?       @relation(fields: [orderId], references: [id])\n  professional Professional @relation(fields: [professionalId], references: [id])\n\n  @@map(\"appointments\")\n}\n\nenum AppointmentStatus {\n  CONFIRMADO\n  PENDENTE\n  CONCLUIDO\n  CANCELADO\n}\n\n// ─── CERTIFICATIONS ───────────────────────────────────────────────────────────\nmodel Certification {\n  id             String    @id @default(uuid()) @db.VarChar(36)\n  professionalId String    @map(\"professional_id\") @db.VarChar(36)\n  name           String    @db.VarChar(200) // 'Técnico em Eletrotécnica'\n  issuedAt       DateTime? @map(\"issued_at\")\n  expiresAt      DateTime? @map(\"expires_at\")\n  issuer         String?   @db.VarChar(150) // instituição emissora\n\n  professional Professional @relation(fields: [professionalId], references: [id], onDelete: Cascade)\n\n  @@map(\"certifications\")\n}\n\nmodel ChatRoom {\n  id        String   @id @default(uuid())\n  orderId   String   @unique @map(\"order_id\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  order    Order         @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  messages ChatMessage[]\n\n  @@map(\"chat_rooms\")\n}\n\nmodel ChatMessage {\n  id        String   @id @default(uuid())\n  roomId    String   @map(\"room_id\")\n  senderId  String   @map(\"sender_id\")\n  type      String   @db.VarChar(10) // \"texto\" | \"imagem\"\n  content   String   @db.Text\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  room   ChatRoom @relation(fields: [roomId], references: [id], onDelete: Cascade)\n  sender User     @relation(fields: [senderId], references: [id], onDelete: Cascade)\n\n  @@map(\"chat_messages\")\n}\n"
}

